  for (var i = 0; i < splitNumber; i++) {
    if ((i * everyLineNumber) < dataCopy || (i * everyLineNumber) === dataCopy) {
      contextCanvas.strokeStyle = activeSplitColor[i]
    } else {
      contextCanvas.strokeStyle = splitColor
    }
    contextCanvas.save()
